// Tell leak zoo: a guessable hash.
// Copyright (C) 2026 Rohan Borade
// SPDX-License-Identifier: Apache-2.0
//
// A "secret" ballot that stores each vote as hash(choice). There are four
// choices, so anyone can hash all four and read every vote off the ledger.

pragma language_version 0.23;

import CompactStandardLibrary;

export ledger voters: Set<Bytes<32>>;
export ledger ballots: Map<Bytes<32>, Bytes<32>>;

witness voterKey(): Bytes<32>;
witness choice(): Uint<8>;

circuit voterTag(sk: Bytes<32>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "ballot:voter"), sk]);
}

export pure circuit choiceHash(c: Uint<8>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "ballot:choice"), (c as Field) as Bytes<32>]);
}

export circuit register(): [] {
  voters.insert(disclose(voterTag(voterKey())));
}

export circuit vote(): [] {
  const tag = disclose(voterTag(voterKey()));
  assert(voters.member(tag), "not a registered voter");
  assert(!ballots.member(tag), "already voted");
  const c = choice();
  assert(c < 4, "there are four candidates");
  ballots.insert(tag, disclose(choiceHash(c)));
}

// Tell leak zoo: the guessable hash, fixed.
// Copyright (C) 2026 Rohan Borade
// SPDX-License-Identifier: Apache-2.0
//
// Each vote is a commitment with a 32-byte random salt held only by the voter.
// Hashing all four choices no longer matches anything on the ledger.

pragma language_version 0.23;

import CompactStandardLibrary;

export ledger voters: Set<Bytes<32>>;
export ledger ballots: Map<Bytes<32>, Bytes<32>>;

witness voterKey(): Bytes<32>;
witness choice(): Uint<8>;
witness ballotSalt(): Bytes<32>;

circuit voterTag(sk: Bytes<32>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "ballot:voter"), sk]);
}

export pure circuit choiceHash(c: Uint<8>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "ballot:choice"), (c as Field) as Bytes<32>]);
}

export circuit register(): [] {
  voters.insert(disclose(voterTag(voterKey())));
}

export circuit vote(): [] {
  const tag = disclose(voterTag(voterKey()));
  assert(voters.member(tag), "not a registered voter");
  assert(!ballots.member(tag), "already voted");
  const c = choice();
  assert(c < 4, "there are four candidates");
  ballots.insert(tag, disclose(persistentCommit<Uint<8>>(c, ballotSalt())));
}

// Tell leak zoo: a guessable hash over an amount.
// Copyright (C) 2026 Rohan Borade
// SPDX-License-Identifier: Apache-2.0
//
// Employees file a "private" salary record so they can later prove it to a
// lender. The record is hash(employee id, salary). The employee id is public
// and a monthly salary in rupees fits in 24 bits, so the salary falls to a
// brute force of about sixteen million hashes.

pragma language_version 0.23;

import CompactStandardLibrary;

export ledger employer: Bytes<32>;
export ledger records: Map<Uint<32>, Bytes<32>>;

witness employerKey(): Bytes<32>;
witness salary(): Uint<32>;

constructor(owner: Bytes<32>) {
  employer = disclose(owner);
}

export pure circuit keyHash(sk: Bytes<32>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "payband:employer"), sk]);
}

export pure circuit recordOf(employee: Uint<32>, pay: Uint<32>): Bytes<32> {
  return persistentHash<Vector<3, Bytes<32>>>([pad(32, "payband:record"), (employee as Field) as Bytes<32>, (pay as Field) as Bytes<32>]);
}

export circuit file(employee: Uint<32>): [] {
  assert(keyHash(employerKey()) == employer, "only the employer files records");
  const pay = salary();
  assert(pay > 0, "salary must be positive");
  records.insert(disclose(employee), disclose(recordOf(employee, pay)));
}

// Tell leak zoo: a branch on a secret.
// Copyright (C) 2026 Rohan Borade
// SPDX-License-Identifier: Apache-2.0
//
// A sealed-bid sale. Bids are committed properly, but the contract files
// each bid under `qualified` or `belowReserve` depending on the hidden
// amount. The public transcript names the set that was touched, so every
// bidder's side of the reserve price is public.

pragma language_version 0.23;

import CompactStandardLibrary;

export ledger reserve: Uint<64>;
export ledger bids: Map<Bytes<32>, Bytes<32>>;
export ledger qualified: Set<Bytes<32>>;
export ledger belowReserve: Set<Bytes<32>>;

witness bidderKey(): Bytes<32>;
witness amount(): Uint<64>;
witness bidSalt(): Bytes<32>;

constructor(r: Uint<64>) {
  reserve = disclose(r);
}

circuit bidderTag(sk: Bytes<32>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "sale:bidder"), sk]);
}

export circuit bid(): [] {
  const tag = disclose(bidderTag(bidderKey()));
  assert(!bids.member(tag), "one bid per bidder");
  const a = amount();
  bids.insert(tag, disclose(persistentCommit<Uint<64>>(a, bidSalt())));
  if (disclose(a >= reserve)) {
    qualified.insert(tag);
  } else {
    belowReserve.insert(tag);
  }
}

// Tell leak zoo: a linkable tag.
// Copyright (C) 2026 Rohan Borade
// SPDX-License-Identifier: Apache-2.0
//
// An "anonymous" staff feedback board. Nobody can tell who a member is, but
// every post carries the same author tag, so all posts by one person line up
// and a single identified post unmasks the rest.

pragma language_version 0.23;

import CompactStandardLibrary;

export ledger members: Set<Bytes<32>>;
export ledger posts: Map<Uint<32>, Bytes<32>>;
export ledger authors: Map<Uint<32>, Bytes<32>>;
export ledger count: Counter;

witness memberKey(): Bytes<32>;

circuit memberTag(sk: Bytes<32>): Bytes<32> {
  return persistentHash<Vector<2, Bytes<32>>>([pad(32, "board:member"), sk]);
}

export circuit join(): [] {
  members.insert(disclose(memberTag(memberKey())));
}

export circuit post(text: Bytes<32>): [] {
  const tag = disclose(memberTag(memberKey()));
  assert(members.member(tag), "members only");
  const n = count.read() as Uint<32>;
  posts.insert(n, disclose(text));
  authors.insert(n, tag);
  count.increment(1);
}

// Tell leak zoo: a secret key on the ledger.
// Copyright (C) 2026 Rohan Borade
// SPDX-License-Identifier: Apache-2.0
//
// The vault remembers its owner by storing the owner's secret key, so the
// first withdrawal hands that key to everyone watching the chain.

pragma language_version 0.23;

import CompactStandardLibrary;

export ledger owner: Bytes<32>;
export ledger withdrawals: Counter;

witness secretKey(): Bytes<32>;

export circuit claim(): [] {
  assert(owner == default<Bytes<32>>, "already claimed");
  owner = disclose(secretKey());
}

export circuit withdraw(): [] {
  assert(owner == disclose(secretKey()), "not the owner");
  withdrawals.increment(1);
}

pragma language_version 0.23;
import CompactStandardLibrary;

export enum VotingState {
    CLOSED,
    OPEN
}

// are there other choices?
export enum VoteChoice {
    BAD,
    WORSE,
    TIE
}

// sealed ledger values cannot be changed after constructor execution
export sealed ledger organizer: Bytes<32>;
export sealed ledger candidate0: Opaque<"string">;
export sealed ledger candidate1: Opaque<"string">;
export ledger votingState: VotingState;
export ledger hashedVoteMap: Map<Bytes<32>, Bytes<32>>;
export ledger registeredVoters: Set<Bytes<32>>;
// tracks who has already revealed, so a vote can only be counted once
export ledger revealedVoters: Set<Bytes<32>>;
export ledger totalVoteCount: Counter;
export ledger candidate0VoteCounter: Counter;
export ledger candidate1VoteCounter: Counter;
export ledger winner: VoteChoice;

witness localGetVote(): VoteChoice;
witness localSk(): Bytes<32>;

constructor(candidateA: Opaque<"string">, candidateB: Opaque<"string">) {
    const _sk = localSk();
    const pubKey = getDappPubKey(_sk);
    organizer = pubKey;
    candidate0 = disclose(candidateA);
    candidate1 = disclose(candidateB);
    votingState = VotingState.CLOSED;
    // open to register to vote
}

// should be available time based
export circuit registerToVote(): [] {
    const _sk = localSk();
    const pubKey = getDappPubKey(_sk);
    assert(!registeredVoters.member(pubKey), "You are already registered to vote");
    assert(votingState == VotingState.CLOSED, "You can only register before voting starts");

    registeredVoters.insert(pubKey);
}

export circuit openVoting(): [] {
    const _sk = localSk();
    const pubKey = getDappPubKey(_sk);
    assert(organizer == pubKey, "You are not the organizer");
    assert(votingState == VotingState.CLOSED, "Voting has already been openend");
    assert(!registeredVoters.isEmpty(), "There are no registered voters");

    votingState = VotingState.OPEN;
}

export circuit commitVote(): [] {
    assert(votingState == VotingState.OPEN, "Voting has not opened yet");
    const _sk = localSk();
    const pubKey = getDappPubKey(_sk);
    assert(registeredVoters.member(pubKey), "You are not registered to vote.");
    assert(!hashedVoteMap.member(pubKey), "Attempt to double vote");
    const _currentVote = localGetVote();
    assert(_currentVote == VoteChoice.BAD || _currentVote == VoteChoice.WORSE, "Please provide a valid vote");


    const hash = commitWithSk(_currentVote as Field as Bytes<32>, _sk);
    hashedVoteMap.insert(pubKey, hash);
    totalVoteCount.increment(1);
}

// check privateState for original vote, if its changed then error
export circuit revealVote(): [] {
    assert(votingState == VotingState.CLOSED, "Voting is still open");

    const _sk = localSk();
    const pubKey = getDappPubKey(_sk);
    // we want to check that they have already voted..
    assert(hashedVoteMap.member(pubKey), "You have not voted yet");
    assert(registeredVoters.member(pubKey), "You are not a registered voter");
    assert(!revealedVoters.member(pubKey), "You have already revealed your vote");

    const vote = localGetVote();
    assert(vote == VoteChoice.BAD || vote == VoteChoice.WORSE, "Please supply a valid vote");

    // here is the money
    const hashedVote = commitWithSk(vote as Field as Bytes<32>, _sk);
    assert(hashedVoteMap.lookup(pubKey) == hashedVote, "Attempt to change the vote!");

    // mark this voter as revealed before counting, so the tally can't be inflated
    revealedVoters.insert(pubKey);

    if(disclose(vote) == VoteChoice.BAD){
        candidate0VoteCounter.increment(1);
    } else if (disclose(vote) == VoteChoice.WORSE) {
        candidate1VoteCounter.increment(1);
    }
}

// should be time based
export circuit closeVoting(): [] {
    const _sk = localSk();
    const pubKey = getDappPubKey(_sk);
    assert(organizer == pubKey, "You are not the organizer");
    assert(!hashedVoteMap.isEmpty(), "You can't close the voting with no votes");
    votingState = VotingState.CLOSED;
}

export circuit checkWinner(): [] {
    const _sk = localSk();
    const pubKey = getDappPubKey(_sk);
    assert(organizer == pubKey, "You are not an organizer");
    assert(votingState == VotingState.CLOSED, "Voting is still open");

    // check for a winner
    if(candidate0VoteCounter > candidate1VoteCounter) {
        winner = VoteChoice.BAD;
    } else if (candidate0VoteCounter < candidate1VoteCounter) {
        winner = VoteChoice.WORSE;
    } else if (candidate0VoteCounter == candidate1VoteCounter) {
        winner = VoteChoice.TIE;
    }
}

// hashing commitment with _sk makes it impossible to brute force a simple 1 or 2
circuit commitWithSk(_vote: Bytes<32>, _sk: Bytes<32>) : Bytes<32> {
    return disclose(persistentHash<Vector<2, Bytes<32>>>([_vote, _sk]));
}

// hash a random "public key" that is only traceable in this dapp
circuit getDappPubKey(_sk: Bytes<32>): Bytes<32> {
  return disclose(persistentHash<Vector<2, Bytes<32>>>([pad(32, "election:pk:"), _sk]));
}
